#!/usr/bin/env node
"use strict";
/**
 * brotli_decode_probe.js - run the demo chain's update-decode step under an
 * arbitrary Node runtime (lab only).
 *
 * This executes demo/electron-payment/update-policy.js - the same policy the
 * Electron update check runs - against local fixture files, so a pinned
 * vulnerable runtime can be compared with the host runtime without any network
 * service and without any exploit code. The artifacts it feeds the decoder are
 * valid Brotli lab markers generated by poc/lab/http/check_brotli.py.
 *
 * Usage:
 *   node brotli_decode_probe.js --feed feed.json --artifact update_body.br \
 *     [--artifact-name br|plain] [--content-encoding br|identity] \
 *     [--policy legacy|hardened] [--stack node:zlib|chromium] \
 *     [--pinned-key publisher.pub.pem] [--allow-encoding identity,br] \
 *     [--chunk-size 64]
 *
 * Prints one JSON evidence record per run, including the runtime versions.
 */

const fs = require("node:fs");
const path = require("node:path");
const crypto = require("node:crypto");
const zlib = require("node:zlib");

const POLICY_MODULE = process.env.UPDATE_POLICY_MODULE ||
  path.join(__dirname, "..", "..", "..", "demo", "electron-payment", "update-policy.js");
const policy = require(POLICY_MODULE);

function argMap(argv) {
  const out = {};
  for (let i = 0; i < argv.length; i += 1) {
    const token = argv[i];
    if (!token.startsWith("--")) continue;
    const eq = token.indexOf("=");
    if (eq !== -1) {
      out[token.slice(2, eq)] = token.slice(eq + 1);
    } else {
      const next = argv[i + 1];
      if (next && !next.startsWith("--")) { out[token.slice(2)] = next; i += 1; } else { out[token.slice(2)] = "true"; }
    }
  }
  return out;
}

async function main() {
  const args = argMap(process.argv.slice(2));
  if (!args.feed || !args.artifact) {
    console.error("usage: brotli_decode_probe.js --feed FEED --artifact FILE [options]");
    return 2;
  }
  const feedJson = JSON.parse(fs.readFileSync(args.feed, "utf8"));
  const artifactBytes = fs.readFileSync(args.artifact);
  const contentEncoding = args["content-encoding"] || "identity";
  const allowEncodings = (args["allow-encoding"] || "identity").split(",").map((s) => s.trim()).filter(Boolean);

  const transport = {
    getFeed: async () => ({ status: 200, json: feedJson, text: JSON.stringify(feedJson) }),
    getArtifact: async () => ({
      status: 200,
      contentEncoding,
      read: async () => Uint8Array.from(artifactBytes)
    })
  };

  const evidence = await policy.runUpdateCheck({
    flavor: args.policy || "legacy",
    stack: args.stack || "node:zlib",
    artifactName: args["artifact-name"] || "br",
    pinnedKeyPem: args["pinned-key"] ? fs.readFileSync(args["pinned-key"], "utf8") : null,
    allowEncodings,
    transport,
    crypto,
    zlib,
    versions: process.versions
  });
  const record = Object.assign({
    probe: "brotli_decode_probe",
    policy_module: POLICY_MODULE,
    runtime: {
      node: process.version,
      v8: process.versions.v8,
      node_decoder_status: policy.nodeDecoderStatus(process.version)
    },
    artifact_file: args.artifact,
    feed_file: args.feed
  }, evidence);
  console.log(JSON.stringify(record));
  return 0;
}

main().then((code) => { process.exitCode = code; },
  (error) => { console.error(String(error && error.stack ? error.stack : error)); process.exitCode = 1; });
